<template><div class="app-container"><el-alert :closable="false" type="info" :title="mode==='review'?'平台审核企业报名；通过后进入企业待分配环节。':'仅草稿可编辑；已发布任务可关闭招募，已通过报名保留。漏报仍仅提醒，不限制报名。'"/>
<el-form inline><el-input v-if="!signupMode" v-model="keyword" placeholder="任务名称" style="width:220px"/><el-button @click="page=1;load()">查询</el-button><el-button v-if="mode==='manage'" type="primary" @click="edit()">创建{{platform?'平台':'企业'}}任务</el-button></el-form>
<el-table :data="rows" v-loading="loading"><el-table-column :prop="signupMode?'task_id':'task_code'" label="任务编号"/><el-table-column prop="title" label="任务名称"/><el-table-column v-if="signupMode" prop="company_name" label="报名企业"/><el-table-column v-if="signupMode" prop="promised_quantity" label="承诺工作量"/><el-table-column v-if="!signupMode" prop="target_quantity" label="目标工作量"/><el-table-column v-if="!signupMode" prop="max_companies" label="企业容量"/><el-table-column v-if="!signupMode" prop="signup_deadline" label="报名截止"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]||row.status}}</template></el-table-column><el-table-column label="操作" width="320"><template #default="{row}"><el-button link @click="view(row)">详情</el-button><template v-if="mode==='manage'"><el-button v-if="row.status==='DRAFT'" link @click="edit(row)">修改</el-button><el-button v-if="row.status==='DRAFT'" link type="primary" @click="publish(row)">发布</el-button><el-button v-if="['PUBLISHED','CLOSED','EXECUTING'].includes(row.status)" link @click="completeTask(row)">完成确认</el-button><el-button v-if="row.status==='PUBLISHED'" link type="danger" @click="close(row)">关闭招募</el-button></template><el-button v-if="mode==='market'&&!platform" link type="primary" @click="apply(row.id)">企业报名</el-button><el-button v-if="mode==='signups'&&row.status==='PENDING'" link @click="withdraw(row)">取消报名</el-button><el-button v-if="mode==='signups'&&['REJECTED','WITHDRAWN'].includes(row.status)" link @click="apply(row.task_id)">修改重提</el-button><el-button v-if="mode==='review'&&row.status==='PENDING'" link type="primary" @click="review(row)">审核</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="page" v-model:limit="size" @pagination="load"/>
<el-dialog v-model="visible" title="任务草稿" width="620px"><el-form label-width="120px"><el-form-item label="任务名称"><el-input v-model="form.title" maxlength="150"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" maxlength="10000"/></el-form-item><el-form-item label="目标工作量"><el-input-number v-model="form.targetQuantity" :min="0.01" :precision="2"/></el-form-item><el-form-item label="单位"><el-input v-model="form.unit" maxlength="20"/></el-form-item><el-form-item label="企业容量"><el-input-number v-model="form.maxCompanies" :min="1" :max="10000" :disabled="!platform"/></el-form-item><el-form-item label="可见范围"><el-tag>{{platform?'面向企业报名':'仅本企业内部使用'}}</el-tag></el-form-item><el-form-item label="报名截止"><el-date-picker v-model="form.signupDeadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="form.startDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="form.endDate" value-format="YYYY-MM-DD"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button></template></el-dialog>
<el-dialog v-model="detailsVisible" title="任务/报名详情与审核意见" width="700px"><el-descriptions :column="2" border><el-descriptions-item v-for="(label,key) in labels" :key="key" :label="label">{{states[detail[key]]||detail[key]}}</el-descriptions-item></el-descriptions><el-alert v-if="detail.readyForAssignment" title="报名已通过，可进入下一阶段的企业任务分配流程。" type="success" :closable="false"/><el-table :data="detail.audits||[]"><el-table-column prop="round_no" label="轮次"/><el-table-column prop="to_status" label="结果"/><el-table-column prop="opinion" label="审核意见"/><el-table-column prop="reviewed_at" label="时间"/></el-table><el-table :data="detail.events||[]"><el-table-column prop="action" label="操作"/><el-table-column prop="opinion" label="说明"/><el-table-column prop="create_time" label="时间"/></el-table></el-dialog>
<el-dialog v-model="reviewVisible" title="平台报名审核"><el-radio-group v-model="decision.approve"><el-radio :value="true">通过</el-radio><el-radio :value="false">驳回</el-radio></el-radio-group><el-input v-model="decision.opinion" type="textarea" maxlength="500" placeholder="审核意见必填"/><template #footer><el-button type="primary" :loading="saving" @click="decide">确认审核</el-button></template></el-dialog>
</div></template>
<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute} from 'vue-router'
import useUserStore from '@/store/modules/user'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const route=useRoute(),user=useUserStore(),platform=computed(()=>user.roles.includes('platform_admin')||user.roles.includes('admin')),mode=computed(()=>route.path.endsWith('task-manage')?'manage':route.path.endsWith('task-signups')?'signups':route.path.endsWith('task-reviews')?'review':'market'),signupMode=computed(()=>['signups','review'].includes(mode.value))
const rows=ref([]),total=ref(0),page=ref(1),size=ref(20),keyword=ref(''),loading=ref(false),saving=ref(false),visible=ref(false),detailsVisible=ref(false),reviewVisible=ref(false),form=ref({}),detail=ref({}),decision=ref({})
const states={DRAFT:'草稿',PUBLISHED:'已发布',CLOSED:'招募已关闭',COMPLETED:'已完成',PENDING:'待审核',APPROVED:'报名通过',REJECTED:'已驳回',WITHDRAWN:'已取消',SHARED:'共享',INTERNAL:'本企业内部',PLATFORM:'平台发布',COMPANY:'企业发布'}
const labels={id:'编号',task_id:'任务编号',title:'标题',description:'说明',publisher_type:'发布方类型',company_id:'企业编号',audience:'可见范围',target_quantity:'目标量',unit:'单位',max_companies:'企业容量',approved_companies:'已通过企业数',approved_quantity:'已通过承诺量',signup_deadline:'报名截止',start_date:'开始日期',end_date:'结束日期',promised_quantity:'本企业承诺量',status:'状态',close_reason:'关闭原因'}
async function load(){loading.value=true;try{const r=await request({url:signupMode.value?'/tasks/signups':'/tasks',params:{mine:mode.value==='manage',review:mode.value==='review',keyword:keyword.value,pageNum:page.value,pageSize:size.value}});rows.value=r.data.rows;total.value=r.data.total}finally{loading.value=false}}
function edit(row){form.value=row?{id:row.id,title:row.title,description:row.description,targetQuantity:Number(row.target_quantity),unit:row.unit,maxCompanies:row.max_companies,audience:row.audience,signupDeadline:String(row.signup_deadline).replace(' ','T'),startDate:String(row.start_date).slice(0,10),endDate:String(row.end_date).slice(0,10),version:row.version}:{unit:'件',maxCompanies:1,targetQuantity:1,audience:platform.value?'SHARED':'INTERNAL'};visible.value=true}
async function save(){saving.value=true;try{await request({url:'/tasks'+(form.value.id?'/'+form.value.id:''),method:form.value.id?'put':'post',data:form.value});visible.value=false;ElMessage.success('草稿已保存');await load()}finally{saving.value=false}}
async function publish(row){await ElMessageBox.confirm('确认发布任务？发布后不能修改草稿字段。');await request({url:`/tasks/${row.id}/publish`,method:'post',data:{version:row.version}});await load()}
async function close(row){const r=await ElMessageBox.prompt('请输入关闭招募原因，已通过报名不撤销','关闭招募',{inputPattern:/\S+/,inputErrorMessage:'原因必填'});await request({url:`/tasks/${row.id}/close`,method:'post',data:{version:row.version,reason:r.value}});await load()}
async function completeTask(row){const r=await ElMessageBox.prompt("请确认全部企业项目已完成，并填写意见","任务完成确认",{inputPattern:/\S+/,inputErrorMessage:"意见必填"});await request({url:`/execution/tasks/${row.id}/complete`,method:"post",data:{version:row.version,opinion:r.value}});await load()}
async function apply(id){const r=await ElMessageBox.prompt('请输入本企业承诺工作量（正数，最多两位小数）','企业报名',{inputPattern:/^\d+(\.\d{1,2})?$/,inputErrorMessage:'请输入有效工作量'});await request({url:`/tasks/${id}/signups`,method:'post',data:{quantity:Number(r.value)}});ElMessage.success('已提交报名，请在企业报名记录查看结果');await load()}
async function withdraw(row){await ElMessageBox.confirm('确认取消待审核报名？已通过报名不能直接取消。');await request({url:`/tasks/signups/${row.id}/withdraw`,method:'post',data:{version:row.version}});await load()}
async function view(row){detail.value=(await request({url:signupMode.value?`/tasks/signups/${row.id}`:`/tasks/${row.id}`})).data;detailsVisible.value=true}
function review(row){decision.value={id:row.id,version:row.version,approve:true,opinion:''};reviewVisible.value=true}
async function decide(){if(!decision.value.opinion?.trim()){ElMessage.warning('请填写审核意见');return}saving.value=true;try{await request({url:`/tasks/signups/${decision.value.id}/review`,method:'post',data:decision.value});reviewVisible.value=false;ElMessage.success('已审核');await load()}finally{saving.value=false}}
watch(mode,()=>{page.value=1;rows.value=[];visible.value=false;detailsVisible.value=false;reviewVisible.value=false;load()},{immediate:true})
</script>
